 const before=baseline.files.find(f=>f.path===d.path), embedded=worker.baseline.files.find(f=>f.path===d.path), actual=readFileSync(d.path,'utf8'), rebuilt=applyUnified(before.content,d.patch);
 return {path:d.path,admission_sha256:sha256(before.content),expected_admission_sha256:d.before_sha256,embedded_baseline_matches:embedded.content===before.content,final_bytes_match:rebuilt===actual,final_sha256:sha256(actual),expected_final_sha256:d.after_sha256,imports_unchanged:JSON.stringify(imports(before.content))===JSON.stringify(imports(actual)),patch_sha256:sha256(d.patch)};
});
const prior=worker.previous_attempts.flatMap(p=>p.scoped_diffs.map(d=>({path:d.path,reconstructed_sha256:sha256(applyUnified(baseline.files.find(f=>f.path===d.path).content,d.patch)),expected_sha256:d.after_sha256})));
const previousArtifact=read('docs/remediation/evidence/W06.08/artifact.json');
const reused=artifact.files.filter(f=>!f.path.startsWith('docs/remediation/'));
const unchangedReused=reused.filter(f=>!['src/identity/erase.ts','src/routes/identity.test.ts'].includes(f.path));
const reuseMatches=unchangedReused.every(f=>previousArtifact.files.some(p=>p.path===f.path&&p.sha256===f.sha256));
