const result={at:new Date().toISOString(),node:process.version,artifact_digest:artifactDigest(artifact),expected_digest:artifact.digest,contract_digest:taskContractDigest(contract),expected_contract:artifact.contract_digest,pin_count:pins.length,all_pins_match:pins.every(p=>p.matches),bad_pins:pins.filter(p=>!p.matches),worker_sha256:sha256(readFileSync(dir+'worker.json')),reconstructed,prior,reused_runtime_toolchain_files:reused.length,unchanged_reused_files:unchangedReused.length,reuse_matches:reuseMatches,worker_checks:checks};
const pass=result.artifact_digest===result.expected_digest&&result.artifact_digest==='14cab1ef403f8ba1403a4ba3058d525ed004dca47f14ef29cedc9ae7e214f40c'&&result.contract_digest===result.expected_contract&&result.all_pins_match&&result.worker_sha256==='d4fca408510e532b9cbf1751d84969cbcfebd3d14800293691dc577c404e4384'&&reconstructed.every(x=>x.admission_sha256===x.expected_admission_sha256&&x.embedded_baseline_matches&&x.final_bytes_match&&x.final_sha256===x.expected_final_sha256&&x.imports_unchanged)&&prior.every(x=>x.reconstructed_sha256===x.expected_sha256)&&reuseMatches&&checks.every(c=>c.exit_code===0&&c.files_match);
console.log(JSON.stringify({...result,pass},null,2));if(!pass)process.exitCode=1;
